// /search: full-text search over every agenda document 351 Watch has read.
// The index is static (Pagefind, built at deploy time into /pagefind/); the browser loads
// only the index chunks and result fragments a query needs, so a search costs no server work.
// Page contract (markup generated by build.py):
//   form#search-form: input#search-q (name=q); optional selects name=state|topic|board|town
//   (values: "MA", topic key, board_key, "MA:Carver"), checkbox name=upcoming value=1,
//   select name=sort (value "date" = newest first); p#search-status (aria-live); ol#search-results.
(() => {
  "use strict";
  const form = document.getElementById("search-form");
  const input = document.getElementById("search-q");
  const status = document.getElementById("search-status");
  const list = document.getElementById("search-results");
  if (!form || !input || !status || !list) return;

  const PAGE = 10;
  const FILTERS = ["state", "town", "topic", "board"];
  const LABELS = {
    state: { MA: "Massachusetts", NY: "New York", RI: "Rhode Island", CT: "Connecticut", NH: "New Hampshire",
      VT: "Vermont", ME: "Maine", NJ: "New Jersey", PA: "Pennsylvania" },
    topic: { battery_storage: "Battery storage", solar: "Solar", data_center: "Data centers",
      moratorium: "Moratoriums", clean_energy_siting: "Clean-energy permit rules",
      "40b_comprehensive_permit": "Affordable housing (40B)", wireless_telecom: "Cell towers",
      zoning_amendment: "Zoning changes", wetlands_filing: "Wetlands permits",
      extraction: "Quarries and gravel pits", large_development: "Large developments" },
    board: { planning_board: "Planning board", zoning_board_of_appeals: "Zoning board of appeals",
      conservation_commission: "Conservation commission", select_board: "Select board or city council",
      town_meeting: "Town meeting warrants" },
  };
  const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const baseTitle = document.title;
  const today = new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 10);

  let pagefind = null; // Promise of the Pagefind module
  let filterCounts = null; // Promise of {filter: {value: count}}
  let vocab = null; // Promise of the spelling vocabulary (most frequent first)
  let generation = 0; // the latest query; older ones stop rendering
  let pending = []; // results not rendered yet
  let loaded = []; // result data rendered so far, for Copy this list and Download CSV
  let tools = null;
  let flaggedOnly = false; // hide agendas with no flagged item (the OCR of a routine agenda is not a lead)
  let weekOnly = false; // only meetings from today through seven days out (a Monday list)
  const todayISO = new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  const weekEndISO = new Date(Date.now() - new Date().getTimezoneOffset() * 60000 + 7 * 86400000).toISOString().slice(0, 10);
  const inWeek = (d) => Boolean(d) && d >= todayISO && d <= weekEndISO;
  let linesDoc = null; // Promise of /data/lines.json: the site's sentence, status, time and place per agenda
  const loadLines = () => (linesDoc ||= fetch("/data/lines.json").then((r) => (r.ok ? r.json() : {})).catch(() => ({})));
  let more = null; // "Show more" button, created on demand

  const load = () =>
    (pagefind ||= import("/pagefind/pagefind.js").then(async (pf) => {
      await pf.options({ excerptLength: 32 });
      return pf;
    }));
  const allFilters = () => (filterCounts ||= load().then((pf) => pf.filters()));
  const loadWords = () =>
    (vocab ||= fetch("/pagefind/words.txt").then((r) => (r.ok ? r.text() : "")).then((t) => t.split("\n").filter(Boolean)));

  const say = (text) => { status.textContent = text; };
  const el = (tag, cls, text) => {
    const n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text) n.textContent = text;
    return n;
  };
  const quoted = (q) => (/^["“].*["”]$/.test(q) ? q : `“${q}”`);
  const plural = (n, one, many) => `${n.toLocaleString("en-US")} ${n === 1 ? one : many}`;
  const fmtDate = (d) => `${MONTHS[+d.slice(5, 7) - 1]} ${+d.slice(8, 10)}, ${d.slice(0, 4)}`;
  const label = (name, value) =>
    name === "town" ? value.replace(/^([A-Z]{2}):(.*)$/, "$2, $1") : (LABELS[name] && LABELS[name][value]) || value;

  // ------------------------------------------------------------------ URL <-> form
  function readParams() {
    const p = new URLSearchParams(location.search);
    input.value = p.get("q") || "";
    for (const field of form.elements) {
      if (!field.name || field === input) continue;
      // a box checked in the HTML stays checked unless the address says otherwise (upcoming=0 after an uncheck)
      if (field.type === "checkbox") field.checked = p.has(field.name) ? p.get(field.name) === field.value : field.defaultChecked;
      else if (field.tagName === "SELECT") {
        const v = p.get(field.name) || "";
        if (v && ![...field.options].some((o) => o.value === v)) field.add(new Option(label(field.name, v), v));
        field.value = v;
      }
    }
    return p;
  }

  function formParams() {
    const p = new URLSearchParams();
    for (const [k, v] of new FormData(form)) if (String(v).trim()) p.append(k, String(v).trim());
    for (const field of form.elements) if (field.type === "checkbox" && field.defaultChecked && !field.checked) p.set(field.name, "0");
    return p;
  }

  // Selects that came with no choices (just "Any") are filled from the index's own values.
  const unfilled = FILTERS.map((f) => form.elements.namedItem(f))
    .filter((s) => s && s.tagName === "SELECT" && s.options.length <= 1);
  async function fillSelects() {
    if (!unfilled.length) return;
    const counts = await allFilters();
    for (const s of unfilled) {
      const current = s.value;
      const have = new Set([...s.options].map((o) => o.value));
      const values = Object.keys(counts[s.name] || {}).sort((a, b) => label(s.name, a).localeCompare(label(s.name, b)));
      for (const v of values) if (!have.has(v)) s.add(new Option(label(s.name, v), v));
      s.value = current;
    }
  }

  // ------------------------------------------------------------------ spelling
  // Pagefind's own typo matching is loose ("batery" finds "Bates"). When a query word has no
  // close match among the first results' highlights, it is corrected against the index's
  // vocabulary (words in 3+ documents, about 45 kB, fetched only then) and searched again.
  const terms = (q) => q.toLowerCase().match(/[a-z]{4,}/g) || [];
  const common = (a, b) => { let i = 0; while (i < a.length && a[i] === b[i]) i++; return i; };

  function distance(a, b, max) { // optimal string alignment distance, or max + 1 if larger
    let prev2 = null;
    let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
    for (let i = 1; i <= a.length; i++) {
      const row = [i];
      let best = i;
      for (let j = 1; j <= b.length; j++) {
        let v = Math.min(prev[j] + 1, row[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
        if (prev2 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) v = Math.min(v, prev2[j - 2] + 1);
        row.push(v);
        best = Math.min(best, v);
      }
      if (best > max) return max + 1;
      prev2 = prev;
      prev = row;
    }
    return prev[b.length];
  }

  // -> [corrected query, words replaced, words neither in the vocabulary nor correctable]
  async function corrected(q, loose) {
    const words = await loadWords();
    if (!words.length) return [q, [], []];
    const known = new Set(words);
    let out = q;
    const fixed = [];
    const unknown = [];
    for (const w of loose) {
      if (known.has(w) || words.some((v) => v.startsWith(w))) continue; // a real word, or a prefix of one
      const max = w.length <= 5 ? 1 : 2;
      let best = null;
      let bestD = max + 1;
      for (const v of words) { // most frequent first: ties go to the commoner word
        if (v[0] !== w[0] || Math.abs(v.length - w.length) > max) continue;
        const d = distance(w, v, max);
        if (d < bestD) { best = v; bestD = d; }
        if (d === 1) break;
      }
      if (best) {
        out = out.replace(new RegExp(`\\b${w}\\b`, "i"), best);
        fixed.push(w);
      } else unknown.push(w);
    }
    return [out, fixed, unknown];
  }

  // ------------------------------------------------------------------ search
  function describe(p) {
    const parts = [];
    if (p.get("topic")) parts.push(`about ${label("topic", p.get("topic")).toLowerCase()}`);
    if (p.get("board")) parts.push(`from the ${label("board", p.get("board")).toLowerCase()}`);
    const towns = p.getAll("town").filter(Boolean);
    if (towns.length) {
      const names = towns.map((t) => label("town", t)); // "Carver, MA" already holds a comma
      parts.push(`in ${names.length > 1 ? names.slice(0, -1).join("; ") + " and " + names[names.length - 1] : names[0]}`);
    }
    else if (p.get("state")) parts.push(`in ${label("state", p.get("state"))}`);
    return parts.length ? " " + parts.join(" ") : "";
  }

  async function find(pf, q, filters, sort) {
    const s = await pf.search(q || null, { filters, sort });
    const results = s ? s.results : [];
    return { results, first: await Promise.all(results.slice(0, PAGE).map((r) => r.data())) };
  }

  async function run(p) {
    const gen = ++generation;
    const q = (p.get("q") || "").replace(/[“”„]/g, '"').trim(); // phrase search takes straight quotes
    const filters = {};
    for (const f of FILTERS) {
      const values = p.getAll(f).filter(Boolean);
      if (values.length === 1) filters[f] = values[0];
      else if (values.length > 1) filters[f] = { any: values }; // several towns: ?town=MA:Carver&town=MA:Plymouth
    }
    const upcoming = p.get("upcoming") === "1";
    const narrowed = Boolean(q || Object.keys(filters).length);
    list.replaceChildren();
    pending = [];
    loaded = [];
    if (tools) tools.hidden = true;
    if (more) more.hidden = true;
    document.title = q ? `${q} | ${baseTitle}` : baseTitle;
    if (!narrowed && !upcoming) {
      say("");
      return;
    }
    say("Searching…");
    list.setAttribute("aria-busy", "true");
    try {
      const pf = await load();
      const sort = p.get("sort") === "date" ? { date: "desc" } : undefined;
      let used = q;
      let typos = [];
      let found = narrowed ? await find(pf, q, filters, sort) : { results: [], first: [] };
      if (q && !q.includes('"')) {
        const marks = found.first.flatMap((d) => (d.excerpt || "").match(/<mark>.*?<\/mark>/g) || [])
          .map((m) => m.slice(6, -7).toLowerCase().replace(/[^a-z0-9]/g, ""));
        const loose = terms(q).filter((w) => !marks.some((m) => common(m, w) >= w.length - 1));
        if (loose.length) {
          const [fixed, words, unknown] = await corrected(q, loose);
          const alt = fixed !== q ? await find(pf, fixed, filters, sort) : null;
          if (alt && alt.results.length) { found = alt; used = fixed; typos = words; }
          // A word found nowhere, with nothing close to it: Pagefind's loose matches are noise.
          else if (unknown.length) found = { results: [], first: [] };
        }
      }
      let results = found.results;
      let soon = 0;
      if (upcoming && (results.length || !narrowed)) {
        // Upcoming meetings (today or later), soonest first, then everything else.
        const dates = Object.keys((await allFilters()).date || {}).filter((d) => d >= today);
        const ahead = dates.length
          ? await pf.search(used || null, { filters: { ...filters, date: { any: dates } }, sort: { date: "asc" } }) : null;
        const first = ahead ? ahead.results : [];
        const ids = new Set(first.map((r) => r.id));
        soon = first.length;
        results = first.concat(results.filter((r) => !ids.has(r.id)));
      }
      if (gen !== generation) return;
      if (!results.length) {
        say(q ? `No agendas match ${quoted(q)}${describe(p)}. Try fewer or different words, or remove a filter.`
          : narrowed ? `No agendas match these filters${describe(p)}.` : "No upcoming meetings found yet.");
        return;
      }
      const n = results.length;
      let msg = !used ? `${plural(n, "agenda", "agendas")}${describe(p)}.`
        : typos.length ? `No agendas contain ${typos.map(quoted).join(" or ")}. Showing ${plural(n, "result", "results")} for ${quoted(used)}${describe(p)} instead.`
        : `${plural(n, "agenda", "agendas")} with ${quoted(used)}${describe(p)}`;
      if (upcoming && !narrowed) msg = `${plural(n, "agenda", "agendas")} for upcoming meetings, soonest first`;
      else if (upcoming) msg = msg.replace(/\.$/, "") + (soon ? ` · ${soon} coming up, shown first` : " · none coming up");
      const examples = document.querySelector(".search-examples");
      if (examples) examples.hidden = Boolean(q);
      pending = results;
      await renderMore(gen, false);
      if (gen === generation) say(msg);
    } catch (err) {
      if (gen !== generation) return;
      console.error(err);
      say("Search isn't working right now. Try again in a few minutes.");
    } finally {
      if (gen === generation) list.removeAttribute("aria-busy");
    }
  }

  async function renderMore(gen, focus) {
    const data = await Promise.all(pending.splice(0, PAGE).map((r) => r.data()));
    if (gen !== generation) return;
    const items = data.map(item);
    list.append(...items);
    loaded.push(...data);
    if (!tools) {
      // the list as text to paste, or as a spreadsheet: every result the search found, up to 300
      tools = el("p", "result-tools");
      const copyBtn = el("button", "link-btn", "Copy this list");
      copyBtn.type = "button";
      const csvBtn = el("button", "link-btn", "Download CSV");
      csvBtn.type = "button";
      copyBtn.addEventListener("click", () => exportResults("copy", copyBtn));
      csvBtn.addEventListener("click", () => exportResults("csv", csvBtn));
      const only = el("label", "result-only");
      const box = document.createElement("input");
      box.type = "checkbox";
      box.addEventListener("change", () => {
        flaggedOnly = box.checked;
        list.classList.toggle("flagged-only", flaggedOnly);
      });
      only.append(box, " Only agendas with a flagged item");
      const week = el("label", "result-only");
      const weekBox = document.createElement("input");
      weekBox.type = "checkbox";
      weekBox.addEventListener("change", () => {
        weekOnly = weekBox.checked;
        list.classList.toggle("week-only", weekOnly);
      });
      week.append(weekBox, " Only the next 7 days");
      tools.append(copyBtn, csvBtn, only, week);
      list.after(tools);
    }
    tools.hidden = !loaded.length;
    if (!more) {
      more = el("button", "search-more");
      more.type = "button";
      more.addEventListener("click", () => {
        more.disabled = true;
        renderMore(generation, true)
          .catch(() => say("We couldn't load more results. Try again."))
          .finally(() => { more.disabled = false; });
      });
      list.after(more);
    }
    more.hidden = !pending.length;
    more.textContent = `Show ${Math.min(PAGE, pending.length)} more`;
    if (focus && items[0]) items[0].querySelector("a").focus();
  }

  async function copyPlain(text) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch (err) {
      const ta = document.createElement("textarea");
      ta.value = text;
      document.body.append(ta);
      ta.select();
      const ok = document.execCommand("copy");
      ta.remove();
      return ok;
    }
  }

  // Every result the search found (up to 300), as lines to paste or a CSV to open in a spreadsheet.
  async function exportResults(kind, btn) {
    const gen = generation;
    const old = btn.textContent;
    btn.disabled = true;
    btn.textContent = "Gathering…";
    try {
      while (pending.length && loaded.length < 300) {
        const data = await Promise.all(pending.splice(0, 50).map((r) => r.data()));
        if (gen !== generation) return;
        loaded.push(...data);
        list.append(...data.map(item));
      }
      if (more) {
        more.hidden = !pending.length;
        more.textContent = `Show ${Math.min(PAGE, pending.length)} more`;
      }
      const L = await loadLines();
      const words = (t) => (t || "").split(",").filter(Boolean).map((k) => LABELS.topic[k] || k).join(", ");
      // one row per flagged item (the site's sentence and status), or one row for the agenda when it has none
      const rows = [];
      for (const d of loaded) {
        const m = d.meta || {};
        const url = /^https?:/i.test(d.url) ? d.url : location.origin + d.url;
        const link = url.replace(/ /g, "%20"); // a town's file name with spaces still pastes as one link
        const at = (L.at && L.at[url]) || ["", "", false];
        const ids = (L.by_url && L.by_url[url]) || [];
        const items = ids.map((id) => L.lines && L.lines[id]).filter((x) => x && x[3] !== "mention");
        if (flaggedOnly && !items.length) continue;
        if (weekOnly && !inWeek(m.date)) continue;
        const base = { town: m.town || "", state: m.state || "", board: m.board || "", date: m.date || "", time: at[0] || "",
          place: at[1] || "", status: at[2] ? "Canceled" : "", document: m.title || "Agenda", topics: words(m.topics),
          agenda_url: link, town_url: m.town_url ? location.origin + m.town_url : "" };
        if (!items.length) rows.push({ ...base, item: "" });
        const seenItems = new Set();
        for (const it of items) {
          if (seenItems.has(it[0])) continue; // one agenda item flagged twice is one line
          seenItems.add(it[0]);
          rows.push({ ...base, item: it[0], status: at[2] ? "Canceled" : (it[9] || ""),
            topics: Array.isArray(it[11]) && it[11].length ? words(it[11].join(",")) : base.topics });
        }
      }
      if (kind === "copy") {
        const byDoc = new Map();
        for (const r of rows) {
          const key = r.agenda_url;
          if (!byDoc.has(key)) byDoc.set(key, { ...r, items: [] });
          if (r.item) byDoc.get(key).items.push(r.status && r.status !== "Canceled" ? `${r.item} (${r.status})` : r.item);
        }
        const text = [...byDoc.values()].map((r) => {
          const head = `${r.town}${r.state && r.state !== "MA" ? `, ${r.state}` : ""} ${r.board}${r.date ? `, ${fmtDate(r.date)}` : ""}${r.time ? `, ${r.time}` : ""}${r.place ? `, ${r.place}` : ""}${r.status === "Canceled" ? " (canceled by the town)" : ""}`;
          return `${head}: ${r.items.length ? r.items.join("; ") : r.document}. ${r.agenda_url}`;
        }).join("\n");
        btn.textContent = (await copyPlain(text)) ? `Copied ${byDoc.size} lines` : "Couldn’t copy";
      } else {
        const esc = (v) => `"${String(v).replace(/"/g, '""')}"`;
        const cols = ["town", "state", "board", "date", "time", "place", "status", "item", "document", "topics", "agenda_url", "town_url"];
        const csv = [cols.join(","), ...rows.map((r) => cols.map((c) => esc(r[c])).join(","))].join("\n");
        const a = document.createElement("a");
        a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
        a.download = "agenda-ahead-search.csv";
        a.click();
        setTimeout(() => URL.revokeObjectURL(a.href), 1000);
        btn.textContent = `Downloaded ${rows.length} rows`;
        if (!rows.length) btn.textContent = "Nothing to download";
      }
      setTimeout(() => { btn.textContent = old; }, 2500);
    } finally {
      btn.disabled = false;
    }
  }

  function item(d) {
    const m = d.meta || {};
    const li = el("li", "result");
    if (m.topics) li.dataset.topics = m.topics;
    if (inWeek(m.date)) li.dataset.week = "1";
    const title = el("a", "result-title", m.title || "Agenda");
    title.href = d.url;
    const when = m.date ? fmtDate(m.date) + (m.date >= today ? ", coming up" : "") : "Undated";
    const meta = el("p", "result-meta", [`${m.town}, ${m.state}`, m.board, when].filter(Boolean).join(" · "));
    const snippet = el("p", "result-snippet");
    excerpt(snippet, d.excerpt || "");
    li.append(title, meta, snippet);
    if (m.town_url) {
      const town = el("a", "result-town", `More from ${m.town}`);
      town.href = m.town_url;
      li.append(town);
    }
    return li;
  }

  // Pagefind excerpts are text with <mark> around matches: build text and <mark> nodes, never innerHTML.
  function excerpt(node, html) {
    const decode = (s) => s.replace(/&(#x?[0-9a-f]+|amp|lt|gt|quot|apos);/gi, (_, e) =>
      e[0] === "#" ? String.fromCodePoint(/^#x/i.test(e) ? parseInt(e.slice(2), 16) : +e.slice(1))
        : { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'" }[e.toLowerCase()]);
    for (const part of html.split(/(<mark>[\s\S]*?<\/mark>)/)) {
      if (part.startsWith("<mark>")) node.append(el("mark", null, decode(part.slice(6, -7))));
      else if (part) node.append(decode(part));
    }
  }

  // ------------------------------------------------------------------ wiring
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const p = formParams();
    const qs = p.toString();
    if (qs !== location.search.slice(1)) history.pushState(null, "", location.pathname + (qs ? "?" + qs : ""));
    run(p);
  });
  form.addEventListener("change", (e) => {
    if (e.target !== input) form.requestSubmit(); // a filter changed: refresh the results
  });
  window.addEventListener("popstate", () => run(readParams()));

  const initial = readParams();
  run(initial);
  if (unfilled.length) {
    const fill = () => fillSelects().catch(() => {});
    if (initial.toString()) fill();
    else if (window.requestIdleCallback) requestIdleCallback(fill, { timeout: 3000 });
    else setTimeout(fill, 1500);
  }
})();
